effect.shader:
float hash(float n) {
    return fract(sin(n * 12.9898) * 43758.5453);
}

void main() {
    float rows = max(blockCount, 1.0);
    float row = floor(acScreenNorm.y * rows);

    // Quantizar o tempo é o que dá o "degrau". Com acTime cru, cada fatia
    // deslizaria continuamente e o resultado pareceria água, não defeito.
    float tick = floor(acTime * max(rate, 0.01));
    float seed = hash(row * 1.7 + tick * 17.3);

    float glitching = step(1.0 - density, seed);
    float shift = (hash(seed * 7.13) - 0.5) * amount * 0.2 * glitching;

    vec2 uv = clamp(acScreenNorm + vec2(shift, 0.0), 0.0, 1.0);
    float split = separation * 0.004 * glitching;

    vec4 result;
    result.r = texture(inputImg, clamp(uv + vec2(split, 0.0), 0.0, 1.0)).r;
    result.g = texture(inputImg, uv).g;
    result.b = texture(inputImg, clamp(uv - vec2(split, 0.0), 0.0, 1.0)).b;
    result.a = texture(inputImg, uv).a;

    fragColor = result;
}
